import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const f=JSON.parse('{"title":"HouseOfFoss","description":"One-Click Tradeboard Installation with House Of FOSS","frontmatter":{"description":"One-Click Tradeboard Installation with House Of FOSS"},"headers":[],"relativePath":"installation-guidelines/getting-started/houseoffoss.md","filePath":"installation-guidelines/getting-started/houseoffoss.md"}'),n={name:"installation-guidelines/getting-started/houseoffoss.md"};function i(s,e,l,d,u,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="houseoffoss" tabindex="-1">HouseOfFoss <a class="header-anchor" href="#houseoffoss" aria-label="Permalink to &quot;HouseOfFoss&quot;">​</a></h1><hr><h2 id="installing-tradeboard-in-the-cloud-with-house-of-foss" tabindex="-1">Installing Tradeboard in the Cloud with House of FOSS <a class="header-anchor" href="#installing-tradeboard-in-the-cloud-with-house-of-foss" aria-label="Permalink to &quot;Installing Tradeboard in the Cloud with House of FOSS&quot;">​</a></h2><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p>You can now install <strong>Tradeboard</strong>, the 100% open-source algorithmic trading platform, directly in the cloud - with just <strong>one click</strong>, using <a href="https://www.houseoffoss.com/" target="_blank" rel="noreferrer"><strong>House of FOSS</strong></a>.</p><p>No complex setups.<br> No manual server configuration.<br> Just pure <strong>self-hosted freedom</strong>.</p><p>House of FOSS provides a platform to install and manage open-source software just like SaaS, but you <strong>own everything</strong>. It’s designed for developers, traders, and startups who want full control without worrying about backend infrastructure.</p><hr><h3 id="_1-what-is-house-of-foss" tabindex="-1">1. What is House of FOSS? <a class="header-anchor" href="#_1-what-is-house-of-foss" aria-label="Permalink to &quot;1. What is House of FOSS?&quot;">​</a></h3><p><strong>House of FOSS</strong> is a managed open-source software platform. It allows you to deploy and run applications like Tradeboard, Excalidraw, or Anything LLM with a single click.</p><p>You don’t need any knowledge of Linux, Docker, or cloud setup, House of FOSS takes care of:</p><ul><li>Installation</li><li>SSL and domain management</li><li>Backups</li><li>Updates</li><li>Scaling</li></ul><p>You just choose the app, give it a name, and launch it.</p><hr><h3 id="_2-getting-started" tabindex="-1">2. Getting Started <a class="header-anchor" href="#_2-getting-started" aria-label="Permalink to &quot;2. Getting Started&quot;">​</a></h3><ol><li>Visit <a href="https://www.houseoffoss.com/" target="_blank" rel="noreferrer"><strong>houseoffoss.com</strong></a>.</li><li>Click on <strong>“Get Started”</strong>.</li><li>Log in or create your workspace.</li><li>In your workspace, go to <strong>Search</strong> and type <strong>“Open Algo”</strong>.</li><li>Select the app from the search results.</li><li>Enter a reference name (e.g., <code>tradeboard</code>).</li><li>Click <strong>Launch Application</strong>.</li></ol><p>Within a few minutes, House of FOSS will automatically:</p><ul><li>Create the instance</li><li>Deploy Tradeboard</li><li>Configure networking and SSL</li></ul><p>After installation, you can click <strong>“Visit Application”</strong> to access Tradeboard.</p><hr><h3 id="_3-initial-configuration" tabindex="-1">3. Initial Configuration <a class="header-anchor" href="#_3-initial-configuration" aria-label="Permalink to &quot;3. Initial Configuration&quot;">​</a></h3><p>After the instance is live, allow <strong>2 to 3 minutes</strong> for backend configuration.<br> Then go to:</p><ul><li><strong>View Application → Config</strong></li></ul><p>This section is where you’ll add your <strong>broker API credentials as per the tradeboard broker config docs</strong>.</p><hr><h3 id="_4-performance-and-latency-considerations" tabindex="-1">4. Performance and Latency Considerations <a class="header-anchor" href="#_4-performance-and-latency-considerations" aria-label="Permalink to &quot;4. Performance and Latency Considerations&quot;">​</a></h3><p>Tradeboard performs best when hosted <strong>close to the exchange region</strong>.<br> If you’re trading on Indian exchanges (like NSE or MCX), choose the <strong>Mumbai region</strong> while deploying in House of FOSS for lower latency and faster order execution.</p><hr><h3 id="_5-requested-enhancements-from-the-community" tabindex="-1">5. Requested Enhancements from the Community <a class="header-anchor" href="#_5-requested-enhancements-from-the-community" aria-label="Permalink to &quot;5. Requested Enhancements from the Community&quot;">​</a></h3><p>We’ve suggested a few improvements to House of FOSS for traders:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td><strong>Mumbai Region Hosting</strong></td><td>Hosting near exchange to reduce latency.</td><td>Planned</td></tr><tr><td><strong>Static IP Support</strong></td><td>Required for broker whitelisting.</td><td>Under consideration</td></tr><tr><td><strong>Custom Domain Mapping</strong></td><td>Use personal domains like <code>myalgo.houseoffoss.net</code>.</td><td>Planned</td></tr></tbody></table><hr><h3 id="_6-why-house-of-foss" tabindex="-1">6. Why House of FOSS? <a class="header-anchor" href="#_6-why-house-of-foss" aria-label="Permalink to &quot;6. Why House of FOSS?&quot;">​</a></h3><ul><li>One-click deployment for Tradeboard and other open-source tools.</li><li>No server management, everything is automated.</li><li>Pay only for <strong>usage</strong>, not monthly subscription.</li><li>100% open-source and self-hosted, <strong>you own the data and code</strong>.</li></ul><hr><h3 id="_7-conclusion" tabindex="-1">7. Conclusion <a class="header-anchor" href="#_7-conclusion" aria-label="Permalink to &quot;7. Conclusion&quot;">​</a></h3><p>With <strong>House of FOSS</strong>, deploying Tradeboard is as easy as clicking a button.<br> You get:</p><ul><li>Self-hosted control</li><li>Free forever open-source trading infrastructure</li><li>Broker integrations</li><li>TradingView automation support</li></ul><p>Whether you’re a trader, developer, or algo enthusiast, this setup gives you the same power as a professional cloud deployment with minimal effort.</p><hr><h4 id="useful-links" tabindex="-1">Useful Links <a class="header-anchor" href="#useful-links" aria-label="Permalink to &quot;Useful Links&quot;">​</a></h4><ul><li><a href="https://www.houseoffoss.com/" target="_blank" rel="noreferrer">House of FOSS</a></li><li><a href="https://github.com/wesoftcorp/tradeboard-docs" target="_blank" rel="noreferrer">Tradeboard GitHub</a></li><li><a href="https://rajeevupadhyay.com/discord" target="_blank" rel="noreferrer">Join Discord Community</a></li></ul>',42)])])}const g=o(n,[["render",i]]);export{f as __pageData,g as default};
